// === Tab: draw ===
let imageScale;
let dotDensity = 2.5;
let damping = 0.6;
let kRadiusFactor = 0.5;
let kSpeed = 3;
let minDistFactor = 2;
let radiusRatio = 3;
let radiusOffset = 0.1;
let nbrParticles = 15000;
let particlesPerFrame = 12;
let reference;
let imgIdiot, imgMeryba;

class Particle
{
    x, y, vx, vy, rad, vrad;
    fx, fy, wt;

    constructor(_x, _y)
    {
        vx = 0;
        vy = 0;
        x = _x;
        y = _y;
        rad = 1;
        vrad = radiusOffset;
    }
}

let particles;

let minRadius, maxRadius, medRadius;
let pixelCount = 0;
let switchTime = [20000, 35000, 50000];
let hasSwitched = [false, false, false];

function setup()
{
    createCanvas(600, 600);

    imgIdiot = loadImage("https://openprocessing.org/sketch/2339026/files/idiot.png");
    imgMeryba = loadImage("https://openprocessing.org/sketch/2339026/files/meryba.png");
    reference = imgIdiot;

    let dwidth = 360;
    let dheight = 360;
    imageScale = width / float(dwidth);

    particles = new Array(nbrParticles);

    frameRate(120);
    smooth();
    stroke(0);
    fill(0);
    ellipseMode(CENTER);

    let medArea = (width * height) / nbrParticles;
    medRadius = sqrt(medArea / PI);
    minRadius = medRadius;
    maxRadius = medRadius * medRadius * 1;
    background(255);
}

function doPhysics()
{
    let maxSpeed = 10.0;
    let maxVradChange = 0.05;

    for (i = 0; i < pixelCount; ++i)
    {
        let px = int(particles[i].x / imageScale);
        let py = int(particles[i].y / imageScale);
        if (px >= 0 && px < reference.width && py >= 0 && py < reference.height)
        {
            let v = int(red)(reference.pixels[py * reference.width + px]);
            let targetRad = map(v / 255.0, 0, 1, minRadius, maxRadius);
            particles[i].rad = lerp(particles[i].rad, targetRad, 0.1);
            let targetVrad = radiusOffset + radiusRatio * (255 - v) / 255;

            let vradDiff = targetVrad - particles[i].vrad;
            particles[i].vrad += constrain(vradDiff, -maxVradChange, maxVradChange);
        }
    }

    for (i = 0; i < pixelCount; ++i)
    {
        let p = particles[i];
        p.fx = p.fy = p.wt = 0;

        p.vx *= damping;
        p.vy *= damping;

        if (abs(p.vx) > maxSpeed)
        {
            p.vx = maxSpeed * (p.vx > 0 ? 1 : -1);
        }
        if (abs(p.vy) > maxSpeed)
        {
            p.vy = maxSpeed * (p.vy > 0 ? 1 : -1);
        }
    }

    for (i = 0; i < pixelCount - 1; ++i)
    {
        var p = particles[i];
        for (j = i + 1; j < pixelCount; ++j)
        {
            let pj = particles[j];
            if (i == j || abs(pj.x - p.x) > p.rad * minDistFactor || abs(pj.y - p.y) > p.rad * minDistFactor)
                continue;

            let dx = p.x - pj.x;
            let dy = p.y - pj.y;
            let distance = sqrt(dx * dx + dy * dy);

            let maxDist = (p.rad + pj.rad);
            let diff = maxDist - distance;
            if (diff > 0)
            {
                let scle = diff / maxDist;
                scle = scle * scle;
                p.wt += scle;
                pj.wt += scle;
                scle = scle * kSpeed / distance;
                p.fx += dx * scle;
                p.fy += dy * scle;
                pj.fx -= dx * scle;
                pj.fy -= dy * scle;
            }
        }
    }

    for (i = 0; i < pixelCount; ++i)
    {
        var p = particles[i];

        var dx, dy, distance, scle, diff;
        var maxDist = p.rad;

        distance = dx = p.x - 0;
        dy = 0;
        diff = maxDist - distance;
        if (diff > 0)
        {
            scle = diff / maxDist;
            scle = scle * scle;
            p.wt += scle;
            scle = scle * kSpeed / distance;
            p.fx += dx * scle;
            p.fy += dy * scle;
        }

        dx = p.x - width;
        dy = 0;
        distance = -dx;
        diff = maxDist - distance;
        if (diff > 0)
        {
            scle = diff / maxDist;
            scle = scle * scle;
            p.wt += scle;
            scle = scle * kSpeed / distance;
            p.fx += dx * scle;
            p.fy += dy * scle;
        }

        distance = dy = p.y - 0;
        dx = 0;
        diff = maxDist - distance;
        if (diff > 0)
        {
            scle = diff / maxDist;
            scle = scle * scle;
            p.wt += scle;
            scle = scle * kSpeed / distance;
            p.fx += dx * scle;
            p.fy += dy * scle;
        }

        dy = p.y - height;
        dx = 0;
        distance = -dy;
        diff = maxDist - distance;
        if (diff > 0)
        {
            scle = diff / maxDist;
            scle = scle * scle;
            p.wt += scle;
            scle = scle * kSpeed / distance;
            p.fx += dx * scle;
            p.fy += dy * scle;
        }
        if (p.wt > 0)
        {
            p.vx += p.fx / p.wt;
            p.vy += p.fy / p.wt;
        }

        if (abs(p.vx) > maxSpeed)
        {
            p.vx = maxSpeed * (p.vx > 0 ? 1 : -1);
        }
        if (abs(p.vy) > maxSpeed)
        {
            p.vy = maxSpeed * (p.vy > 0 ? 1 : -1);
        }

        p.x += p.vx;
        p.y += p.vy;
    }
}

function draw()
{
    background(255);

    // if (millis() > switchTime[0] && !hasSwitched[0])
    // {
    //     reference = imgMeryba;
    //     hasSwitched[0] = true;
    // }

    if (pixelCount < nbrParticles)
    {
        for (i = 0; i < particlesPerFrame; i++)
        {
            particles[pixelCount++] = new Particle(random(width), random(height));
        }
    }

    doPhysics();

    for (i = 0; i < pixelCount; ++i)
    {
        strokeWeight(particles[i].vrad);
        point(particles[i].x, particles[i].y);
    }
}

